167			late.VersionID != "seat-v3" {
168			t.Fatalf("版本应按生效时刻排列为 v1/v2/v3: %q, %q, %q",
169				old.VersionID, early.VersionID, late.VersionID)
170		}
171	
172		// 旧版：登记结束仍是 3 月 31 日（永不因后续登记改变），
173		// 实际结束被 v2 进一步提前到 3 月 10 日，改显示由 v2 替代。
174		if old.UnitPrice != 150 || !old.Start.Equal(dtOldStart) {
175			t.Fatalf("旧版登记信息异常: %+v", old)
176		}
177		if old.End == nil || !old.End.Equal(dtOldEnd) {
178			t.Fatalf("旧版登记结束应仍为 3 月 31 日, got %v", old.End)
179		}
180		if old.EffectiveEnd == nil || !old.EffectiveEnd.Equal(dtEarlyHandoff) {
181			t.Fatalf("旧版实际结束应被 v2 提前到 3 月 10 日, got %v", old.EffectiveEnd)
182		}
183		if old.Replaces != "" || old.SupersededBy != "seat-v2" {
184			t.Fatalf("旧版替代关系异常: Replaces=%q SupersededBy=%q",
185				old.Replaces, old.SupersededBy)
186		}
187	
188		// 更早版本：实际有效区间为 [3 月 10 日, 3 月 20 日)，替代 v1。
189		if early.UnitPrice != 180 {
190			t.Fatalf("更早版本单价应为 180, got %d", early.UnitPrice)
191		}
192		if !early.Start.Equal(dtEarlyHandoff) || !early.EffectiveStart.Equal(dtEarlyHandoff) {
193			t.Fatalf("更早版本开始时刻应为 3 月 10 日: %+v", early)
194		}
195		if early.End == nil || !early.End.Equal(dtLateHandoff) ||
196			early.EffectiveEnd == nil || !early.EffectiveEnd.Equal(dtLateHandoff) {
197			t.Fatalf("更早版本有效区间应为 [03-10, 03-20): 登记结束=%v 实际结束=%v",
198				early.End, early.EffectiveEnd)
199		}
200		if early.Replaces != "seat-v1" || early.SupersededBy != "" {
201			t.Fatalf("更早版本替代关系异常: Replaces=%q SupersededBy=%q",
202				early.Replaces, early.SupersededBy)
203		}
204	
205		// 较晚版本：起止时间不变，原登记的替代来源 v1 保持原值，
206		// 不能为了把替代关系排列成 v1→v2→v3 连续链而改写成 v2。
207		if late.UnitPrice != 200 || !late.Start.Equal(dtLateHandoff) {
208			t.Fatalf("较晚版本登记信息异常: %+v", late)
209		}
210		if late.End != nil || late.EffectiveEnd != nil {
211			t.Fatalf("较晚版本应仍持续有效: 登记结束=%v 实际结束=%v",
212				late.End, late.EffectiveEnd)
213		}
214		if late.Replaces != "seat-v1" || late.SupersededBy != "" {
215			t.Fatalf("较晚版本替代来源应保持 v1 不变: Replaces=%q SupersededBy=%q",
216				late.Replaces, late.SupersededBy)
217		}
218	}
219	
220	// 二次截短后按指定时刻查询：选择依据是各版本的实际有效区间，
221	// 不能沿用登记顺序（v1、v3、v2），也不能沿用 v1 的月底登记结束日期。
222	// [03-01, 03-10) 选 v1，3 月 10 日交接点（含）至 3 月 20 日前选 v2，
223	// 3 月 20 日交接点（含）起选 v3；查询返回的单价与版本列表一致。
224	func TestEffectiveVersionAtAfterSecondTruncation(t *testing.T) {
225		now, _ := fixedClock(dtOldStart)
226		b := NewBook(WithClock(now))
227		oldEnd := dtOldEnd
228		earlyEnd := dtLateHandoff
229		for _, req := range []RegisterRequest{
230			{ItemID: "seat", VersionID: "seat-v1", UnitPrice: 150, Start: dtOldStart, End: &oldEnd},
231			{ItemID: "seat", VersionID: "seat-v3", UnitPrice: 200, Start: dtLateHandoff, Replaces: "seat-v1"},
232			{ItemID: "seat", VersionID: "seat-v2", UnitPrice: 180, Start: dtEarlyHandoff, End: &earlyEnd, Replaces: "seat-v1"},
233		} {
234			if err := b.RegisterVersion(req); err != nil {
235				t.Fatalf("register %s: %v", req.VersionID, err)
236			}
237		}
238	
239		cases := []struct {
240			name      string
241			at        time.Time
242			versionID string
243			unitPrice int64
244		}{
245			{"v1 生效起点-含", dtOldStart, "seat-v1", 150},
246			{"v2 交接点前一纳秒", dtEarlyHandoff.Add(-time.Nanosecond), "seat-v1", 150},
247			{"v2 交接点-含", dtEarlyHandoff, "seat-v2", 180},
248			{"v2 区间中段", time.Date(2026, 3, 15, 12, 0, 0, 0, time.UTC), "seat-v2", 180},
249			{"v3 交接点前一纳秒", dtLateHandoff.Add(-time.Nanosecond), "seat-v2", 180},
250			{"v3 交接点-含", dtLateHandoff, "seat-v3", 200},
251			{"v1 登记结束当天仍选 v3", dtOldEnd, "seat-v3", 200},
252			{"v1 登记结束之后仍选 v3", dtOldEnd.Add(24 * time.Hour), "seat-v3", 200},
253		}
254		for _, c := range cases {
255			t.Run(c.name, func(t *testing.T) {
256				view, err := b.EffectiveVersionAt("seat", c.at)
257				if err != nil {
258					t.Fatalf("查询应命中版本: %v", err)
259				}
260				if view.VersionID != c.versionID || view.UnitPrice != c.unitPrice {
261					t.Fatalf("时刻 %v 应选 %s（%d 分）, got %s（%d 分）",
262						c.at, c.versionID, c.unitPrice, view.VersionID, view.UnitPrice)
263				}
264			})
265		}
266	
267		// 首版开始之前没有任何生效版本，不拿邻近的 v1 补位。
268		if _, err := b.EffectiveVersionAt("seat", dtOldStart.Add(-time.Nanosecond)); !errors.Is(err, ErrNoEffectiveVersion) {
269			t.Fatalf("首版开始之前应返回 ErrNoEffectiveVersion, got %v", err)
270		}
271	}
272	
273	// 报价与查询共用同一套实际有效期判断：时钟停在 v2 的有效区间内时，
274	// 引用 v2 按 180 分确认，引用实际结束已提前到 3 月 10 日的 v1 则以
275	// version_expired 拒绝——即使 v1 的登记结束 3 月 31 日仍在将来。
276	func TestQuoteAfterSecondTruncation(t *testing.T) {
277		now, setNow := fixedClock(dtOldStart)
278		b := NewBook(WithClock(now))
279		oldEnd := dtOldEnd
280		earlyEnd := dtLateHandoff
281		for _, req := range []RegisterRequest{
282			{ItemID: "seat", VersionID: "seat-v1", UnitPrice: 150, Start: dtOldStart, End: &oldEnd},
283			{ItemID: "seat", VersionID: "seat-v3", UnitPrice: 200, Start: dtLateHandoff, Replaces: "seat-v1"},
284			{ItemID: "seat", VersionID: "seat-v2", UnitPrice: 180, Start: dtEarlyHandoff, End: &earlyEnd, Replaces: "seat-v1"},
285		} {
286			if err := b.RegisterVersion(req); err != nil {
287				t.Fatalf("register %s: %v", req.VersionID, err)
288			}
289		}
290	
291		acceptedAt := time.Date(2026, 3, 15, 10, 0, 0, 0, time.UTC)
292		setNow(acceptedAt)
293	
294		fresh, err := b.Quote(QuoteRequest{
295			RequestID: "dt-v2-360", ItemID: "seat", VersionID: "seat-v2", Quantity: 2,
296		})
297		if err != nil {
298			t.Fatalf("引用 v2 是正常受理，err 应为空: %v", err)
299		}
300		if !fresh.Confirmed || fresh.UnitPrice != 180 || fresh.Total != 360 {
301			t.Fatalf("v2 报价应按 180 分确认 360 分: %+v", fresh)
302		}
303		if !fresh.AcceptedAt.Equal(acceptedAt) || fresh.Reason != ReasonNone {
304			t.Fatalf("v2 确认结果受理时刻/拒绝原因异常: %+v", fresh)
305		}
306	
307		expired, err := b.Quote(QuoteRequest{
308			RequestID: "dt-v1-expired", ItemID: "seat", VersionID: "seat-v1", Quantity: 2,
309		})
310		if err != nil {
311			t.Fatalf("引用 v1 是正常受理，err 应为空: %v", err)
312		}
313		if expired.Confirmed || expired.Reason != ReasonVersionExpired {
314			t.Fatalf("v1 实际结束已提前到受理时刻之前，应以 version_expired 拒绝: %+v", expired)
315		}
316		if expired.UnitPrice != 0 || expired.Total != 0 {
317			t.Fatalf("拒绝结果单价/总价应为零: 单价=%d 总价=%d", expired.UnitPrice, expired.Total)
318		}
319	}
