			}
			if out.Reason != c.reason {
				t.Fatalf("原因=%q, want %q", out.Reason, c.reason)
			}
			// 结果必须保留请求中的费率项、版本和数量，不自动改用另一版，
			// 并记录精确的受理时刻（含毫秒小数部分）。
			if out.Request != req {
				t.Fatalf("请求来源未保留: %+v vs %+v", out.Request, req)
			}
