				nv.EffectiveEnd == nil || !nv.EffectiveEnd.Equal(subNewEnd) ||
				nv.Replaces != "seat-v1" || nv.SupersededBy != "" {
				t.Fatalf("新版被失败登记改写: %+v", nv)
			}
		})
	}
