		{"结束早于开始一纳秒", subBase.Add(300 * time.Millisecond), subBase.Add(300*time.Millisecond - time.Nanosecond)},
		{"结束早于开始一毫秒", subBase.Add(300 * time.Millisecond), subBase.Add(299 * time.Millisecond)},
